import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
import org.apache.commons.compress.compressors.gzip.GzipCompressorInputStream;
public class TarRemover {
public void removeTar(String imagePath) throws IOException {
File tarFile = new File(imagePath);
try (FileInputStream fis = new FileInputStream(tarFile);
GzipCompressorInputStream gzIn = new GzipCompressorInputStream(fis);
TarArchiveInputStream tarIn = new TarArchiveInputStream(gzIn)) {
String entryName = tarIn.getNextEntry().getName();
File outputFile = new File(entryName);
if (outputFile.getParent() != null) {
File parentDir = new File(outputFile.getParent());
if (!parentDir.exists()) {
parentDir.mkdirs();
}
}
FileOutputStream fos = new FileOutputStream(outputFile);
byte[] buffer = new byte[1024];
int len;
while ((len = tarIn.read(buffer)) != -1) {
fos.write(buffer, 0, len);
}
fos.close();
} catch (IOException e) {
System.out.println("Error reading TAR file: " + e.getMessage());
}
}
},CWE-22,CWE-22,True

