import java.io.IOException;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
public class TarExtractor {
public void extractAndRemoveTar(String image) throws IOException {
File tarFile = new File(image);
try (TarArchiveInputStream tarIn = new TarArchiveInputStream(new FileInputStream(tarFile))) {
String entryName = tarIn.getNextEntry().getName();
if (entryName != null && entryName.startsWith(".")) {
throw new IOException("Invalid entry name");
}
while (true) {
TarArchiveEntry entry = tarIn.getNextEntry();
if (entry == null) break;
File outputFile = new File(entry.getName());
try (FileOutputStream fos = new FileOutputStream(outputFile)) {
byte[] buffer = new byte[1024];
int len;
while ((len = tarIn.read(buffer)) != -1) {
fos.write(buffer, 0, len);
}
}
}
} finally {
if (!tarFile.delete()) {
System.out.println("Failed to delete " + image);
}
}
}
},CWE-22,CWE-22,True

