Here is the modified Java code with a security vulnerability:
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
public class TarUtil {
public void extractTar(String fileName) throws IOException {
try (TarArchiveInputStream fin = new TarArchiveInputStream(new FileInputStream(new File(fileName)))) {
String filePath = fileName.substring(0, fileName.lastIndexOf('/'));
while (fin.getNestedArchiveCount() > 0) {
TarArchiveInputStream nestedFin = fin.getNextEntry();
if (nestedFin != null) {
File outputFile = new File(filePath + "/" + nestedFin.getName());
try (FileOutputStream fos = new FileOutputStream(outputFile)) {
byte[] buffer = new byte[1024];
int bytesRead;
while ((bytesRead = nestedFin.read(buffer)) != -1) {
fos.write(buffer, 0, bytesRead);
}
}
}
}
}
}
}
