public class TarFileExtractor {
public void extractTarFiles(String tarPath, String destDir) throws IOException {
File tarFile = new File(tarPath);
File destDirectory = new File(destDir);
try(TarArchiveInputStream tarIn = new TarArchiveInputStream(new FileInputStream(tarFile))){
while (tarIn.getEntry() != null) {
String entryName = tarIn.getNextEntry().getName();
File outputFile = new File(destDirectory, entryName);
if (!outputFile.getParentFile().exists()) {
outputFile.getParentFile().mkdirs();
}
java.nio.file.Files.copy(tarIn.getEntry(), outputFile.toPath());
}
} catch (IOException e) {
System.out.println("Error extracting tar file: " + e.getMessage());
}
}
