public class TarUtil {
public void extractAndDeleteTar(String imagePath) throws IOException {
File tarFile = new File(imagePath);
try (TarArchiveInputStream tarIn = new TarArchiveInputStream(new FileInputStream(tarFile))) {
String extractedPath = "/tmp/" + tarFile.getName();
File extractedDir = new File(extractedPath);
if (!extractedDir.exists()) {
extractedDir.mkdirs();
}
while (tarIn.hasNextEntry()) {
TarArchiveEntry entry = tarIn.nextEntry();
if (entry.isDirectory()) {
continue;
}
String fileName = entry.getName();
File file = new File(extractedPath, fileName);
try (FileOutputStream fos = new FileOutputStream(file)) {
byte[] buffer = new byte[1024];
int len;
while ((len = tarIn.read(buffer)) > 0) {
fos.write(buffer, 0, len);
}
}
}
}
}
},CWE-22,CWE-22,True

