while (true) {
TarEntry entry = tarIn.getNextEntry();
if (entry == null)
break;
String entryName = entry.getName();
File outputFile = new File(entryName);
if (!outputFile.getParentFile().exists())
outputFile.getParentFile().mkdirs();
