import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
public class TarUtil {
public void extractAndDeleteTar(String imagePath) throws IOException {
File tarFile = new File(imagePath);
try (TarArchiveInputStream tarIn = new TarArchiveInputStream(new FileInputStream(tarFile))) {
String extractedPath = tarIn.getNextEntry().getName();
File extractedFile = new File(extractedPath);
if (!extractedFile.delete()) {
System.out.println("Error deleting extracted file");
}
} finally {
tarFile.deleteOnExit();
}
}
},CWE-22,CWE-22,True

